import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:lazerus_app/core/macros/modifiers/normalization/normalization_modifier.dart';
import 'package:lazerus_app/features/debug/application/debug_devices_controller.dart';
import 'package:lazerus_app/features/macros/presentation/node_modules/macro_editor_node_module.dart';
import 'package:lazerus_app/features/macros/presentation/node_modules/normalization/normalization_macro_editor_node_module.dart';
import 'package:lazerus_core/lazerus_core.dart';

void main() {
  testWidgets('creates a PCM node and changes its output mode to value', (
    tester,
  ) async {
    final module = NormalizationMacroEditorNodeModule();
    final node = module.createNode(
      const MacroEditorPaletteEntry(
        id: 'normalization',
        moduleKind: normalizationModifierKind,
        section: MacroEditorPaletteSection.modules,
        icon: Icons.tune_outlined,
        title: 'Normalization',
        subtitle: 'Rolling audio dynamics',
      ),
      newId: () => 'normalization',
    )!;
    MacroNode? replacement;
    final context = MacroEditorNodeViewContext(
      node: node,
      state: MacroEditorNodePresentationState(
        graph: MacroGraph(
          id: 'macro',
          name: 'Macro',
          nodes: <MacroNode>[node],
          edges: const <MacroEdge>[],
        ),
        enabled: true,
        devicesById: const <String, DebugDevice>{},
        devices: const <DebugDevice>[],
      ),
      replaceNode: (value) => replacement = value,
      removeNode: () {},
    );

    expect(node.ports.last.type, MacroPortType.triggerMonoAudio);
    expect(
      NormalizationModifierConfiguration.fromNodeParameters(
        node.parameters,
      ).windowDuration,
      const Duration(seconds: 5),
    );

    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(
          body: Builder(
            builder: (buildContext) =>
                module.buildInspector(buildContext, context),
          ),
        ),
      ),
    );

    await tester.tap(
      find.byKey(const Key('normalization-output-mode-normalization')),
    );
    await tester.pumpAndSettle();
    await tester.tap(find.text('Value (0–1)').last);
    await tester.pump();

    expect(replacement, isNotNull);
    expect(replacement!.ports.last.type, MacroPortType.triggerLevel);
    expect(
      NormalizationModifierConfiguration.fromNodeParameters(
        replacement!.parameters,
      ).outputMode,
      NormalizationOutputMode.value,
    );
  });

  testWidgets('updates the rolling duration in seconds', (tester) async {
    final module = NormalizationMacroEditorNodeModule();
    final node = module.createNode(
      const MacroEditorPaletteEntry(
        id: 'normalization',
        moduleKind: normalizationModifierKind,
        section: MacroEditorPaletteSection.modules,
        icon: Icons.tune_outlined,
        title: 'Normalization',
        subtitle: 'Rolling audio dynamics',
      ),
      newId: () => 'normalization',
    )!;
    MacroNode? replacement;
    final context = MacroEditorNodeViewContext(
      node: node,
      state: MacroEditorNodePresentationState(
        graph: MacroGraph(
          id: 'macro',
          name: 'Macro',
          nodes: <MacroNode>[node],
          edges: const <MacroEdge>[],
        ),
        enabled: true,
        devicesById: const <String, DebugDevice>{},
        devices: const <DebugDevice>[],
      ),
      replaceNode: (value) => replacement = value,
      removeNode: () {},
    );

    await tester.pumpWidget(
      MaterialApp(
        home: Scaffold(
          body: Builder(
            builder: (buildContext) =>
                module.buildInspector(buildContext, context),
          ),
        ),
      ),
    );

    await tester.enterText(
      find.byKey(const Key('normalization-window-normalization-5')),
      '7',
    );
    await tester.pump();

    expect(
      NormalizationModifierConfiguration.fromNodeParameters(
        replacement!.parameters,
      ).windowDuration,
      const Duration(seconds: 7),
    );
  });
}
